marks={1:[10,13,20,22,24],2:[6,8,16],3:[1,4,28],4:[11,14,18,26],6:[0,3,5,7,9,21,24],7:[12,17],8:[28],9:[2,6,8,10,26],10:[4,19,24],11:[12,21],12:[0,15,17],13:[9,26,28],14:[3,6,22,24],15:[12,20],16:[8,17],17:[0,4,10,14,27],18:[2,6],19:[16,25],20:[9,18,21,23],21:[14,27],22:[1,3,12],23:[7,17,19,22,25],24:[5,10,15,28]}
pts={(r,c) for r,cs in marks.items() for c in cs}
# evaluate conflicts among 3-cell vertical stamp: if two triggered centres separated by 2 rows same col, overlaps endpoints
from collections import defaultdict
occ=defaultdict(list)
for r,c in pts:
 for dr,val in zip((-1,0,1),(6,1,4)):occ[r+dr,c].append(((r,c),val))
clash=[(p,x) for p,x in occ.items() if len({v for _,v in x})>1]
print('n marks',len(pts),'conflicting stencil cells',clash)
# target centers adjacent to any source cells within stamp area?
print('same-col centers sorted', {c:sorted(r for r,cc in pts if cc==c) for c in range(29) if sum(cc==c for r,cc in pts)>1})

H,W=26,29
marks={1:[10,13,20,22,24],2:[6,8,16],3:[1,4,28],4:[11,14,18,26],6:[0,3,5,7,9,21,24],7:[12,17],8:[28],9:[2,6,8,10,26],10:[4,19,24],11:[12,21],12:[0,15,17],13:[9,26,28],14:[3,6,22,24],15:[12,20],16:[8,17],17:[0,4,10,14,27],18:[2,6],19:[16,25],20:[9,18,21,23],21:[14,27],22:[1,3,12],23:[7,17,19,22,25],24:[5,10,15,28]}
g=[[7]*W for _ in range(H)]
for r,cs in marks.items():
 for c in cs:g[r][c]=0
g[7][14],g[8][14],g[9][14]=6,1,4
assert len(g)==26 and all(len(row)==29 for row in g)
# Transpose the source vertical motif while preserving its top-to-bottom color sequence left-to-right.
out=[row[:] for row in g]
for r in sorted(marks):
 for c in sorted(marks[r]):
  for dc,val in zip((-1,0,1),(6,1,4)):
   if 0<=c+dc<W: out[r][c+dc]=val
assert len(out)==26 and all(len(row)==29 for row in out)
import json
print(json.dumps(out,separators=(',',':')))

